//! Conservative feedback calibration for live intelligence decisions.
//! Calibration never creates a directional signal; it only scales confidence
//! after a minimum amount of historical evidence exists.
#[derive(Debug,Clone,Copy,PartialEq)]pub struct PerformanceFeedback{pub samples:usize,pub avg_confidence:f64,pub avg_risk:f64,pub avg_data_quality:f64,pub avg_agreement:f64}
#[derive(Debug,Clone,Copy,PartialEq)]pub struct ConfidenceCalibration{pub multiplier:f64,pub calibrated_confidence:f64,pub sufficient_history:bool}
pub fn calibrate_confidence(raw:f64,feedback:PerformanceFeedback)->ConfidenceCalibration{if feedback.samples<30{return ConfidenceCalibration{multiplier:1.0,calibrated_confidence:raw.clamp(0.0,100.0),sufficient_history:false};}let reliability=(feedback.avg_data_quality*0.35+feedback.avg_agreement*0.35+(100.0-feedback.avg_risk)*0.30).clamp(0.0,100.0);let history_strength=(feedback.samples as f64/200.0).clamp(0.0,1.0);let target=(0.75+reliability/100.0*0.35).clamp(0.75,1.10);let multiplier=(1.0+(target-1.0)*history_strength).clamp(0.75,1.10);ConfidenceCalibration{multiplier,calibrated_confidence:(raw*multiplier).clamp(0.0,100.0),sufficient_history:true}}
#[cfg(test)]mod tests{use super::*;#[test]fn insufficient_history_does_not_change_confidence(){let c=calibrate_confidence(80.0,PerformanceFeedback{samples:10,avg_confidence:70.0,avg_risk:20.0,avg_data_quality:90.0,avg_agreement:90.0});assert_eq!(c.multiplier,1.0);assert_eq!(c.calibrated_confidence,80.0);assert!(!c.sufficient_history);}#[test]fn weak_history_reduces_confidence(){let c=calibrate_confidence(80.0,PerformanceFeedback{samples:200,avg_confidence:80.0,avg_risk:80.0,avg_data_quality:30.0,avg_agreement:30.0});assert!(c.calibrated_confidence<80.0);}#[test]fn calibration_is_bounded(){let c=calibrate_confidence(99.0,PerformanceFeedback{samples:1000,avg_confidence:99.0,avg_risk:0.0,avg_data_quality:100.0,avg_agreement:100.0});assert!(c.calibrated_confidence<=100.0);assert!(c.multiplier<=1.10);}}
